<?php
require __DIR__.'/config/database.php';require __DIR__.'/includes/functions.php';require_admin();verify_csrf();
if($_SERVER['REQUEST_METHOD']==='POST'){require_admin();$action=$_POST['action']??'';if($action==='save'){$id=(int)($_POST['id']??0);$name=trim($_POST['nama_perangkat']??'');$jenis=trim($_POST['jenis']??'');$ket=trim($_POST['keterangan']??'');if($name===''){flash('Nama perangkat wajib diisi.','error');}else{if($id){$st=$pdo->prepare('UPDATE perangkat SET nama_perangkat=?,jenis=?,keterangan=? WHERE id_perangkat=?');$st->execute([$name,$jenis,$ket,$id]);flash('Perangkat diperbarui.');}else{$st=$pdo->prepare('INSERT INTO perangkat(nama_perangkat,jenis,keterangan) VALUES(?,?,?)');$st->execute([$name,$jenis,$ket]);flash('Perangkat ditambahkan.');}}header('Location: perangkat.php');exit;}if($action==='delete'){$st=$pdo->prepare('DELETE FROM perangkat WHERE id_perangkat=?');$st->execute([(int)$_POST['id']]);flash('Perangkat dihapus.');header('Location: perangkat.php');exit;}}
$pageTitle='Data Perangkat';$edit=null;if(isset($_GET['edit'])&&is_admin()){$st=$pdo->prepare('SELECT * FROM perangkat WHERE id_perangkat=?');$st->execute([(int)$_GET['edit']]);$edit=$st->fetch();}$rows=$pdo->query('SELECT p.*,COUNT(d.id_detail) pemakaian FROM perangkat p LEFT JOIN detail_checklist d ON d.id_perangkat=p.id_perangkat GROUP BY p.id_perangkat ORDER BY p.nama_perangkat')->fetchAll();require __DIR__.'/includes/header.php';
?><div class="welcome-row"><div><span class="eyebrow">INVENTARIS SEKOLAH</span><h1>Data Perangkat</h1><p>Daftar perangkat elektronik yang menjadi bagian dari checklist konservasi.</p></div></div><div class="content-split"><?php if(is_admin()): ?><section class="panel form-panel"><div class="panel-heading"><div><h2><?= $edit?'Edit perangkat':'Tambah perangkat' ?></h2><p>Lengkapi data perangkat elektronik.</p></div></div><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= (int)($edit['id_perangkat']??0) ?>"><div class="form-field"><label>Nama perangkat</label><input class="form-control" name="nama_perangkat" value="<?= e($edit['nama_perangkat']??'') ?>" placeholder="Contoh: Lampu LED" required></div><div class="form-field"><label>Jenis</label><input class="form-control" name="jenis" value="<?= e($edit['jenis']??'Elektronik') ?>" placeholder="Elektronik"></div><div class="form-field"><label>Keterangan</label><textarea class="form-control" name="keterangan" rows="3" placeholder="Keterangan singkat"><?= e($edit['keterangan']??'') ?></textarea></div><button class="btn btn-primary btn-full">Simpan Perangkat</button><?php if($edit): ?><a class="back-link" href="perangkat.php">Batal edit</a><?php endif; ?></form></section><?php endif; ?><section class="panel table-panel"><div class="panel-heading"><div><h2>Daftar perangkat</h2><p><?= count($rows) ?> perangkat tersedia.</p></div></div><div class="table-wrap"><table><thead><tr><th>Perangkat</th><th>Jenis</th><th>Checklist</th><?php if(is_admin()): ?><th>Aksi</th><?php endif; ?></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><div class="table-person"><span class="stat-icon green">ϟ</span><span><b><?= e($r['nama_perangkat']) ?></b><small class="block muted"><?= e($r['keterangan']) ?></small></span></div></td><td><?= e($r['jenis']) ?></td><td><?= (int)$r['pemakaian'] ?> kali</td><?php if(is_admin()): ?><td><div class="inline-actions"><a class="btn btn-ghost btn-sm" href="perangkat.php?edit=<?= (int)$r['id_perangkat'] ?>">Edit</a><form method="post" onsubmit="return confirm('Hapus perangkat ini? Detail checklist terkait juga akan terhapus.')"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)$r['id_perangkat'] ?>"><button class="btn btn-danger btn-sm">Hapus</button></form></div></td><?php endif; ?></tr><?php endforeach; ?></tbody></table></div></section></div><?php require __DIR__.'/includes/footer.php'; ?>
